	"strings"
)

func solve(numCourses int, prerequisites [][]int) []int {
	// Return the course order (smallest available first), or an empty list.
	return []int{}
}

func atoi(s string) int {
	v, _ := strconv.Atoi(strings.TrimSpace(s))
	return v
}

type Tok struct {
	t []string
	i int
}

func (k *Tok) next() string {
	if k.i < len(k.t) {
		k.i++
		return k.t[k.i-1]
	}
	return "0"
}

func readInt1(tk *Tok) []int {
	n := atoi(tk.next())
	res := make([]int, n)
	for i := 0; i < n; i++ {
		res[i] = atoi(tk.next())
	}
	return res
}

func readInt2(tk *Tok) [][]int {
	n := atoi(tk.next())
	res := make([][]int, n)
	for i := 0; i < n; i++ {
		res[i] = readInt1(tk)
	}
	return res
}

func main() {
	data, _ := io.ReadAll(os.Stdin)
	lines := strings.Split(strings.ReplaceAll(string(data), "\r", ""), "\n")
	line := func(i int) string {
		if i < len(lines) {
			return lines[i]
		}
		return ""
	}
	numCourses := atoi(strings.TrimSpace(line(0)))
	prerequisites := readInt2(&Tok{t: strings.Fields(line(1))})
	result := solve(numCourses, prerequisites)
	parts := make([]string, len(result))
	for i, v := range result {
		parts[i] = fmt.Sprint(v)
	}
	fmt.Println(strings.Join(parts, " "))
}

